// Simulate the parseThresholds function from the CLI
function parseThresholds(thresholdStrs = []) {
  if (!thresholdStrs || thresholdStrs.length === 0) {
    return null;
  }

  const thresholds = {};
  for (const thresholdStr of thresholdStrs) {
    const match = thresholdStr.match(/^([a-z_]+)=(\d*\.?\d+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
    }
    const [, metricId, scoreStr] = match;
    const score = parseFloat(scoreStr);
    if (isNaN(score) || score < 0 || score > 1) {
      throw new Error(`Invalid threshold for ${metricId}: ${scoreStr}. Must be a number between 0 and 1.`);
    }
    thresholds[metricId] = score;
  }
  return thresholds;
}

// Test cases
console.log('Testing parseThresholds...\n');

// Test 1: Valid thresholds
console.log('Test 1: Valid thresholds');
try {
  const result = parseThresholds(['exact_match=0.9', 'toxicity=0.95']);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

// Test 2: No thresholds
console.log('\nTest 2: No thresholds');
try {
  const result = parseThresholds([]);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

// Test 3: Malformed threshold (missing equals)
console.log('\nTest 3: Malformed threshold (missing equals)');
try {
  const result = parseThresholds(['exact_match0.9']);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

// Test 4: Invalid metric name (with uppercase)
console.log('\nTest 4: Invalid metric name (with uppercase)');
try {
  const result = parseThresholds(['Exact_Match=0.9']);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

// Test 5: Invalid score (too high)
console.log('\nTest 5: Invalid score (too high)');
try {
  const result = parseThresholds(['exact_match=1.5']);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

// Test 6: Invalid score (negative)
console.log('\nTest 6: Invalid score (negative)');
try {
  const result = parseThresholds(['exact_match=-0.1']);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

// Test 7: Repeated thresholds (last one wins)
console.log('\nTest 7: Repeated thresholds (last one wins)');
try {
  const result = parseThresholds(['exact_match=0.5', 'exact_match=0.9']);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

// Test 8: Different valid formats
console.log('\nTest 8: Different valid formats');
try {
  const result = parseThresholds(['exact_match=1', 'toxicity=0.5', 'length_variance=0.75']);
  console.log('Result:', result);
} catch (error) {
  console.log('Error:', error.message);
}

