// Test: generates and writes report
try {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    generatedAt: '2024-01-01T00:00:00.000Z'
  });
  assert(report.metadata.totalSamples === 1, 'generates and writes report - total samples');

  const dir = createTempDir();
  const jsonPath = writeReport({
    report,
    format: 'json',
    reportPath: path.join(dir, 'report.json')
  });
  const markdownPath = writeReport({
    report,
    format: 'markdown',
    reportPath: path.join(dir, 'report.md')
  });

  assert(fs.existsSync(jsonPath), 'generates and writes report - JSON exists');
  assert(fs.existsSync(markdownPath), 'generates and writes report - Markdown exists');
} catch (error) {
  console.error(`✗ Test failed:`, error.message);
  failCount++;
}

// Test: validates thresholds
try {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });

  const validErrors = validateThresholds({ exact_match: 0.5 }, evaluations);
  assert(validErrors.length === 0, 'validates thresholds - valid threshold');

  const unknownMetricErrors = validateThresholds({ unknown_metric: 0.5 }, evaluations);
  assert(unknownMetricErrors.length > 0, 'validates thresholds - unknown metric detected');
  assert(unknownMetricErrors[0].includes('Unknown metric id'), 'validates thresholds - unknown metric message');

  const invalidScoreErrors = validateThresholds({ exact_match: 1.5 }, evaluations);
  assert(invalidScoreErrors.length > 0, 'validates thresholds - invalid score detected');
  assert(invalidScoreErrors[0].includes('Invalid threshold'), 'validates thresholds - invalid score message');
} catch (error) {
  console.error(`✗ Test failed:`, error.message);
  failCount++;
}

// Test: evaluates thresholds
try {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'World'],
    references: ['hello', 'world']
  });

  const results = evaluateThresholds({ exact_match: 0.5 }, evaluations);
  assert(results.length === 1, 'evaluates thresholds - single result');
  assert(results[0].metric === 'exact_match', 'evaluates thresholds - metric name');
  assert(results[0].min === 0.5, 'evaluates thresholds - min value');
  assert(results[0].score === 1, 'evaluates thresholds - score');
  assert(results[0].passed === true, 'evaluates thresholds - passed status');
} catch (error) {
  console.error(`✗ Test failed:`, error.message);
  failCount++;
}

// Test: fails threshold when metric without score
try {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: []
  });

  const results = evaluateThresholds({ exact_match: 0.5 }, evaluations);
  assert(results[0].score === null, 'fails threshold when metric without score - null score');
  assert(results[0].passed === false, 'fails threshold when metric without score - failed status');
} catch (error) {
  console.error(`✗ Test failed:`, error.message);
  failCount++;
}

// Test: generates report with thresholds
try {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5 },
    generatedAt: '2024-01-01T00:00:00.000Z'
  });

  assert(report.passed === true, 'generates report with thresholds - passed status');
  assert(report.thresholds && report.thresholds.length === 1, 'generates report with thresholds - threshold count');
  assert(report.thresholds[0].metric === 'exact_match', 'generates report with thresholds - metric name');
} catch (error) {
  console.error(`✗ Test failed:`, error.message);
  failCount++;
}

// Test: includes threshold results in markdown report
try {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5 },
    generatedAt: '2024-01-01T00:00:00.000Z'
  });

  const dir = createTempDir();
  const markdownPath = writeReport({
    report,
    format: 'markdown',
    reportPath: path.join(dir, 'report.md')
  });

  const content = fs.readFileSync(markdownPath, 'utf8');
  assert(content.includes('## Thresholds'), 'includes threshold results in markdown - has Thresholds section');
  assert(content.includes('exact_match'), 'includes threshold results in markdown - has metric name');
  assert(content.includes('PASS'), 'includes threshold results in markdown - has PASS status');
} catch (error) {
  console.error(`✗ Test failed:`, error.message);
  failCount++;
}

cleanup();

console.log(`\n=== Test Results ===`);
console.log(`Passed: ${passCount}`);
console.log(`Failed: ${failCount}`);
console.log(`Total: ${passCount + failCount}`);

if (failCount > 0) {
  process.exit(1);
}

